#include <stdint.h>
#include "app_config.h"
#include "esp8266_at.h"
#include "gpio_led.h"

/* SysTick registers. */
#define SYSTICK_BASE    0xE000E010UL
#define SYSTICK_CTRL    (*(volatile uint32_t *)(SYSTICK_BASE + 0x00U))
#define SYSTICK_LOAD    (*(volatile uint32_t *)(SYSTICK_BASE + 0x04U))
#define SYSTICK_VAL     (*(volatile uint32_t *)(SYSTICK_BASE + 0x08U))

/* STM32F103 uses HSI 8 MHz in this minimal Cube for VSCode project. */
#define SYSTEM_CLOCK_HZ  8000000UL

static volatile uint32_t g_ms_ticks = 0;

void SysTick_Handler(void)
{
    g_ms_ticks++;
}

uint32_t APP_GetMillis(void)
{
    return g_ms_ticks;
}

static void delay_ms(uint32_t ms)
{
    uint32_t start = g_ms_ticks;

    while ((g_ms_ticks - start) < ms)
    {
        /* wait */
    }
}

static void systick_init(void)
{
    SYSTICK_LOAD = (SYSTEM_CLOCK_HZ / 1000UL) - 1UL;
    SYSTICK_VAL = 0U;
    SYSTICK_CTRL = 0x07U;
}

int main(void)
{
    uint32_t last_wifi_retry = 0U;
    uint8_t esp_ready = 0U;

    systick_init();
    LED_Init();
    delay_ms(100);

    esp_ready = ESP8266_Init();
    last_wifi_retry = APP_GetMillis();

    while (1)
    {
        LED_Process();

        if (esp_ready != 0U)
        {
            ESP8266_Process();
        }
        else if ((APP_GetMillis() - last_wifi_retry) >= ESP8266_WIFI_RETRY_MS)
        {
            last_wifi_retry = APP_GetMillis();
            esp_ready = ESP8266_Init();
        }
    }
}
